using UnityEngine;
using Golfin.Physics.Viewer;
using System.Reflection;

public class DiagBallSpawn {
    public static void Run() {
        var ctrl = Object.FindFirstObjectByType<PhysicsLabController>();
        if (ctrl == null) { Debug.Log("[DBG] PhysicsLabController not found"); return; }
        var f_spawn  = typeof(PhysicsLabController).GetField("_ballSpawnPoint", BindingFlags.NonPublic|BindingFlags.Instance);
        var f_anchor = typeof(PhysicsLabController).GetField("_runtimeTeeAnchor", BindingFlags.NonPublic|BindingFlags.Instance);
        var spawn  = f_spawn?.GetValue(ctrl) as Transform;
        var anchor = f_anchor?.GetValue(ctrl) as Transform;
        string spawnName = spawn == null ? "NULL" : spawn.name;
        string spawnPos  = spawn == null ? "n/a" : spawn.position.ToString("F3");
        string anchorName = anchor == null ? "NULL" : anchor.name;
        string anchorPos  = anchor == null ? "n/a" : anchor.position.ToString("F3");
        Debug.Log("[DBG] _ballSpawnPoint = " + spawnName + " at " + spawnPos);
        Debug.Log("[DBG] _runtimeTeeAnchor = " + anchorName + " at " + anchorPos);
        var ba = Object.FindFirstObjectByType<BallAnimator>();
        var ball = ba != null ? ba.CurrentBall : null;
        string ballPos = ball == null ? "NULL" : ball.position.ToString("F3");
        Debug.Log("[DBG] CurrentBall at " + ballPos);
        int count = 0;
        foreach (Transform c in ctrl.transform) {
            if (c.name == "_RuntimeTeeAnchor")
                Debug.Log("[DBG] child anchor #" + (++count) + ": " + c.position.ToString("F3"));
        }
    }
}
